_GuideMessage:
class _GuideMessage extends StatelessWidget {
  final String label;
  final Color color;
  final Widget? leading;
  final VoidCallback? onTap;
  final String? hint;
  final bool focused;
  final Color? focusFill;
  final Color? focusInk;

  const _GuideMessage({
    super.key,
    required this.label,
    required this.color,
    this.leading,
    this.onTap,
    this.hint,
    this.focused = false,
    this.focusFill,
    this.focusInk,
  }) : assert(
         !focused || (focusFill != null && focusInk != null),
         'A focused guide message needs focus colors.',
       );

  @override
  Widget build(BuildContext context) {
    final content = AnimatedContainer(
      duration: const Duration(milliseconds: 130),
      curve: Curves.easeOutCubic,
      padding: const EdgeInsets.symmetric(horizontal: 16),
      decoration: focused
          ? BoxDecoration(
              color: focusFill,
              borderRadius: BorderRadius.circular(8),
              boxShadow: [
                BoxShadow(
                  color: color.withValues(alpha: 0.28),
                  blurRadius: 16,
                  spreadRadius: -5,
                ),
              ],
            )
          : null,
      child: Row(
        children: [
          if (leading != null) ...[leading!, const SizedBox(width: 8)],
          Flexible(
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: focused ? focusInk : color,
                fontSize: 11,
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
        ],
      ),
    );
    if (onTap == null) {
      return Semantics(label: label, child: content);
    }
    return Semantics(
      excludeSemantics: true,
      button: true,
      focusable: true,
      focused: focused,
      selected: focused,
      label: label,
      hint: hint,
      onTap: onTap,
      child: MouseRegion(
        cursor: SystemMouseCursors.click,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: onTap,
          child: content,
        ),
      ),
    );
  }
}

_ChannelMark:
class _ChannelMark extends StatelessWidget {
  final String? logoUrl;
  final double size;
  final bool selected;
  final IptvStyleTokens tokens;

  const _ChannelMark({
    required this.logoUrl,
    this.size = 38,
    required this.selected,
    required this.tokens,
  });

  @override
  Widget build(BuildContext context) {
    final fallback = Icon(
      Icons.live_tv_rounded,
      size: 19,
      color: selected ? tokens.focusInk : tokens.fgMid,
    );
    final logo = logoUrl?.trim();
    return Container(
      width: size,
      height: size,
      padding: const EdgeInsets.all(6),
      decoration: BoxDecoration(
        color: selected
            ? tokens.focusInk!.withValues(alpha: 0.08)
            : Colors.white.withValues(alpha: 0.055),
        borderRadius: BorderRadius.circular(9),
      ),
      child: logo == null || logo.isEmpty
          ? fallback
          : CachedNetworkImage(
              imageUrl: logo,
              cacheManager: DebrifyImageCache.iptvLogos,
              fit: BoxFit.contain,
              memCacheHeight: 96,
              placeholder: (_, _) => fallback,
              errorWidget: (_, _, _) => fallback,
            ),
    );
  }
}
